  "implementation": "def solve(case):
    if not isinstance(case, dict) or 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError('Invalid case structure')
    nodes = case['nodes']
    req_symbols = set(case['required_symbols'])
    if not nodes:
        raise ValueError('No nodes')
    node_map = {}
    for n in nodes:
        if 'id' not in n or 'parent' not in n or 'symbol' not in n or 'depth' not in n or 'removable' not in n:
            raise ValueError('Node missing required fields')
        node_map[n['id']] = n
    children = {nid: [] for nid in node_map}
    for n in nodes:
        pid = n.get('parent')
        if pid is not None:
            if pid not in children:
                raise ValueError('Parent id not found')
            children[pid].append(n['id'])
    # find root
    roots = [nid for nid, n in node_map.items() if n.get('parent') is None]
    if len(roots) != 1:
        raise ValueError('Must have exactly one root')
    root_id = roots[0]
    # start with all nodes retained
    retained = set(node_map.keys())
    removed_order = []
    # sort by depth descending then id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        if not n['removable']:
            continue
        if n['symbol'] in req_symbols:
            continue
        # check if any immediate child is still retained
        if any(child in retained for child in children.get(nid, [])):
            continue
        # tentatively remove this node
        cand_retained = retained - {nid}
        # ensure all required symbols still exist
        if not all(any(node_map[rid]['symbol'] == sym for rid in cand_retained) for sym in req_symbols):
            continue
        retained = cand_retained
        removed_order.append(nid)
    retained_sorted = sorted(retained)
    return {'removed_node_ids': removed_order, 'retained_node_ids': retained_sorted}"
}
